KG42.register("edges-901ecbc2f4169d810f777f32",{"id":"S-2fb66957024c8b3f","source":"COMP-09e23646758c214d","type":"links","target":"COMP-a66dbdae6253f618","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["14-stackelberg_pv_sharing"],"assertions":[{"id":"14-stackelberg_pv_sharing::v141-c-R014::E::v141-c-R014-E001","paper":"14-stackelberg_pv_sharing","rule_id":"v141-c-R014","rule_ref":"14-stackelberg_pv_sharing::v141-c-R014","record":{"edge_id":"v141-c-R014-E001","source":"product.local_energy","target":"pricing.local","type":"links","constraint_ids":["v141-c-R014-C001"],"evidence_ids":["v141-b-g03-E12"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R014-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-09e23646758c214d","target":"COMP-a66dbdae6253f618","source_occurrence_id":"14-stackelberg_pv_sharing::v141-c-R014::V::product.local_energy","target_occurrence_id":"14-stackelberg_pv_sharing::v141-c-R014::V::pricing.local","source_unit_id":"14-stackelberg_pv_sharing::v141-a-M03::product.local_energy","target_unit_id":"14-stackelberg_pv_sharing::v141-a-M03::pricing.local","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Cournot benchmark internal buying-price assumption. | Cournot benchmark internal selling-price boundary condition. | Cournot benchmark internal selling-price condition for sufficient selling energy. | Cournot benchmark local microgrid market with seller-role prosumers as players.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g03-E12","v141-b-g03-E17"]},"active":true,"source_signature":"3a41c7fa465c2ca58194995be99227ffd15bb213bf7038157902b22542645f72","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M03","source_definition":"The benchmark's local market product is PV energy supplied within the microgrid. Scope: Cournot-model local microgrid market benchmark.","target_definition":"The quantity of local energy supplied enters the selling-price function p_s = a - bE^s. Scope: Cournot benchmark local microgrid market with seller-role prosumers as players. The internal selling price should equal the utility-grid price λ^b when no PV energy can be supplied in the microgrid. Scope: Cournot benchmark internal selling-price boundary condition. Condition: E^s = 0. The internal selling price should be minimized to λ^s under the stated sufficient-supply condition. Scope: Cournot benchmark internal selling-price condition for sufficient selling energy. Condition: E^s ≥ E^b. The internal buying price is assumed equal to the utility price λ^s. Scope: Cournot benchmark internal buying-price assumption.","constraints":[{"constraint_id":"v141-c-R014-C001","kind":"mathematical","role":"core","statement":"The quantity of local energy supplied enters the selling-price function p_s = a - bE^s. Scope: Cournot benchmark local microgrid market with seller-role prosumers as players.","expression":"p_s = a - bE^s","formalization_origin":"source","template_id":null,"members":["product.local_energy","pricing.local"],"variable_refs":["var_ps","var_es"],"parameter_refs":["par_a","par_b"],"evidence_ids":["v141-b-g03-E12"]}],"evidence":[{"evidence_id":"v141-b-g03-E12","location":{"location_id":"src-ed046424ff-p10-c1r4__v141-a-M03-pricing","page":10,"printed_page":null,"section":"Appendix B Cournot Model","anchor_text":"the local market inside a microgrid by using the Cournot model. As referring to model of [28]–[30], ","equation_id":"(31)-(32)","figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"formula"},"source_text":"Cournot model was applied in the electricity market with multiple producers (i.e., power plants). We have reformulated the local market inside a microgrid by using the Cournot model. As referring to model of [28]–[30], the players in the local market are only limited to seller role prosumers, the relation between selling prices and amount of energy is\np_s = a - bE^s. \\quad (31)\nIf E^s = 0, there is no PV energy that can be supplied in the microgrid. Therefore, the selling price should be equal to the price of utility grid \\lambda^b. If E^s \\ge E^b, the selling energy is more than the required energy. Then, the selling price should be minimized to \\lambda^s. Thus, the price function (31) should include the points (0,\\lambda^b) and (E^b,\\lambda^s), and the parameter a and b can be obtained\na = \\lambda^b, \\quad b = (\\lambda^b - \\lambda^s)/E^b. \\quad (32)"}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Cournot benchmark internal buying-price assumption. | Cournot benchmark internal selling-price boundary condition. | Cournot benchmark internal selling-price condition for sufficient selling energy. | Cournot benchmark local microgrid market with seller-role prosumers as players.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g03-E12","v141-b-g03-E17"]},"source_record":{"edge_id":"v141-c-R014-E001","source":"product.local_energy","target":"pricing.local","type":"links","constraint_ids":["v141-c-R014-C001"],"evidence_ids":["v141-b-g03-E12"]},"paper_scope_note":"Stackelberg ESM, deviation billing, and the Cournot baseline are kept separate; buying/selling branches, numerical cases, and the no-deviation/penalty conditions are retained with the declaration."}}],"assertion_ids":["14-stackelberg_pv_sharing::v141-c-R014::E::v141-c-R014-E001"]});
